<script>
window.addEventListener('DOMContentLoaded', function () {
  if (!window.BABYLON) return;

  var canvas = document.getElementById('reqCanvas3d');
  var loading = document.getElementById('reqLoading');
  var toolbar = document.getElementById('reqToolbar');
  var stageTitle = document.getElementById('reqStageTitle');
  var stageText = document.getElementById('reqStageText');
  var eqEl = document.getElementById('reqEquation');
  var lumiBox = document.getElementById('reqLumi');
  var lumiText = document.getElementById('reqLumiText');
  var raySlider = document.getElementById('reqRayCount');
  var rayVal = document.getElementById('reqRayVal');
  var cosToggle = document.getElementById('reqCosToggle');
  var prevBtn = document.getElementById('reqPrev');
  var nextBtn = document.getElementById('reqNext');
  var rayRow = document.getElementById('reqRayRow');
  var cosRow = document.getElementById('reqCosRow');
  if (!canvas || !toolbar) return;

  function prefix() {
    return /\/levels\//.test(window.location.pathname) ? '../' : '';
  }

  var FRONT_ALPHA = Math.PI / 2;
  var ROOM_TARGET = new BABYLON.Vector3(0, 1.25, 0);

  var STAGES = [
    {
      id: 'cam', name: '1) Bild & Kamerastrahl',
      text: 'Zum Rendern schicken wir für <strong>jedes Pixel</strong> der Bildfläche einen Strahl in die Szene – hier als 5×5-Raster vor der Kamera. Für den Walkthrough wählen wir <strong>ein grün markiertes Pixel</strong> und verfolgen genau diesen Strahl bis zum Bodenpunkt <strong>x</strong>.',
      hl: 'Lo', lumi: 'In der Praxis hat das Bild Millionen Pixel – wir zoomen auf einen einzelnen Strahl.',
      showGrid: true, showRays: false, showCos: false,
      view: { alpha: FRONT_ALPHA, beta: Math.PI / 2.48, radius: 12.5, target: [0, 1.35, 0.15] }
    },
    {
      id: 'lo', name: '2) L<sub>o</sub> am Trefferpunkt',
      text: 'Die Pixel-Farbe ist die ausgehende Helligkeit L<sub>o</sub>(x, ω<sub>o</sub>): Licht, das am Trefferpunkt x in Richtung der Kamera (ω<sub>o</sub>) abgestrahlt wird.',
      hl: 'Lo', lumi: 'ω<sub>o</sub> zeigt vom Boden zurück zur Kamera – so „sieht“ das Pixel den Punkt x.',
      showRays: false, showCos: false,
      view: { alpha: FRONT_ALPHA + 0.22, beta: Math.PI / 2.75, radius: 6.8, target: [0.12, 0.45, 0.08] }
    },
    {
      id: 'le', name: '3) Emission L<sub>e</sub>',
      text: 'L<sub>o</sub> beginnt mit L<sub>e</sub>: leuchtet x selbst? Der Boden ist nicht emissiv → L<sub>e</sub> = 0. Nur die gelbe Deckenlampe hat L<sub>e</sub> > 0.',
      hl: 'Le', lumi: 'Nicht jede Fläche leuchtet von selbst – der Boden reflektiert nur!',
      showRays: false, showCos: false,
      view: { alpha: FRONT_ALPHA - 0.08, beta: Math.PI / 2.55, radius: 9.5, target: [0, 1.85, 0] }
    },
    {
      id: 'hemi', name: '4) Hemisphäre / Integral',
      text: 'Der Rest kommt vom Integral ∫<sub>Ω</sub>: Am Punkt x müssen wir alle möglichen eingehenden Richtungen ω<sub>i</sub> auf der Hemisphäre über der Normalen n betrachten.',
      hl: 'int', lumi: 'Stell dir eine Halbkugel auf den Boden – jeder Strahl ist ein Kandidat für eingehendes Licht.',
      showRays: true, showCos: false,
      view: { alpha: FRONT_ALPHA + 0.18, beta: Math.PI / 2.85, radius: 5.8, target: [0.12, 0.38, 0.08] }
    },
    {
      id: 'wi', name: '5) Ein Strahl ω<sub>i</sub>',
      text: 'Wir verfolgen einen konkreten ω<sub>i</sub>-Strahl von x. Er trifft die weiße Decke – dort ist L<sub>e</sub> ebenfalls 0 (die Decke leuchtet nicht von selbst).',
      hl: 'int', lumi: '', showRays: false, showCos: false, singleWi: true,
      view: { alpha: FRONT_ALPHA + 0.12, beta: Math.PI / 2.65, radius: 7.2, target: [0.08, 1.55, 0.05] }
    },
    {
      id: 'li', name: '6) Rekursion & L<sub>i</sub>',
      text: 'Von der Decke schicken wir einen weiteren Strahl zur Lampe. L<sub>i</sub>(x, ω<sub>i</sub>) ist die Radiance, die bei x aus Richtung ω<sub>i</sub> ankommt – berechnet durch Rekursion am Decke-Trefferpunkt.',
      hl: 'Li', lumi: 'L<sub>i</sub> ist „Licht von woanders“ – wir verfolgen den Strahl weiter, bis eine Quelle L<sub>e</sub> > 0 liefert.',
      showRays: false, showCos: false, recurse: true,
      view: { alpha: FRONT_ALPHA - 0.05, beta: Math.PI / 2.5, radius: 8.8, target: [0, 2.05, 0] }
    },
    {
      id: 'cos', name: '7) Cosinus (ω<sub>i</sub>·n)',
      text: 'Der Term (ω<sub>i</sub>·n) ist das Skalarprodukt aus eingehender Richtung und Normalen n. Steht ω<sub>i</sub> senkrecht auf der Fläche, trägt der Strahl voll bei; liegt er flach, fast gar nicht.',
      hl: 'cos', lumi: 'Das ist das Lambert’sche Cosinus-Gesetz – schräges Licht wirkt schwächer.',
      showRays: false, showCos: true, singleWi: true,
      view: { alpha: FRONT_ALPHA + 0.2, beta: Math.PI / 2.9, radius: 5.2, target: [0.12, 0.32, 0.08] }
    },
    {
      id: 'brdf', name: '8) BRDF f<sub>r</sub>',
      text: 'f<sub>r</sub> beschreibt das Material: Wie viel einfallendes Licht wird in Richtung ω<sub>o</sub> reflektiert? Diffuser Boden ≈ 0,7, perfektes Schwarz = 0, Spiegel → 1 in Spiegelrichtung.',
      hl: 'fr', lumi: 'Die BRDF ist die „Farbe und Oberflächenart“ in der Formel.',
      showRays: false, showCos: false, singleWi: true,
      view: { alpha: FRONT_ALPHA + 0.16, beta: Math.PI / 2.88, radius: 4.9, target: [0.12, 0.28, 0.08] }
    },
    {
